/* Nexus AI workspace — extracted from index.html v3. Classic script; keep execution order. */

/* ===== original script 21: inline-21 ===== */
(function(){
  var AIVA_B64 = "";
  var ov = null, back = null, frame = null, blobUrl = null, prevActive = null;

  function buildOnce(){
    if (ov) return;
    var bin = atob(AIVA_B64);
    var bytes = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    blobUrl = URL.createObjectURL(new Blob([bytes], { type: "text/html" }));
    ov = document.createElement("div");
    ov.id = "aivaOverlay";
    frame = document.createElement("iframe");
    frame.setAttribute("sandbox", "allow-scripts allow-same-origin allow-forms allow-popups allow-modals allow-downloads");
    frame.title = "Nexus AI";
    frame.src = blobUrl;
    ov.appendChild(frame);
    back = document.createElement("div");
    back.id = "aivaBack";
    back.innerHTML = '<span class="arr">\u25B2</span>ALL TOOLS';
    back.title = "Kembali ke All Tools";
    back.addEventListener("click", closeAiva);
    document.body.appendChild(ov);
    document.body.appendChild(back);
  }

  function openAiva(){
    buildOnce();
    prevActive = document.querySelector(".nav-tab.active");
    document.querySelectorAll(".nav-tab").forEach(function(t){ t.classList.remove("active"); });
    var b = document.getElementById("nav-aiva");
    if (b) b.classList.add("active");
    ov.style.display = "block";
    back.style.display = "flex";
    requestAnimationFrame(function(){ ov.classList.add("on"); });
  }

  window.__nxBuildAiva = buildOnce;
  window.__nxOriginalOpenAiva = openAiva;

  function closeAiva(){
    if (!ov) return;
    ov.classList.remove("on");
    setTimeout(function(){ ov.style.display = "none"; back.style.display = "none"; }, 300);
    var b = document.getElementById("nav-aiva");
    if (b) b.classList.remove("active");
    if (prevActive) prevActive.classList.add("active");
  }

  window.__nxOriginalCloseAiva = closeAiva;

  document.addEventListener("keydown", function(e){
    if (e.key === "Escape" && ov && ov.classList.contains("on")) closeAiva();
  });

  window.addEventListener("message", function(e){
    if (e.data && e.data.__atn === "close") closeAiva();
  });

  function patchZx(){
    document.querySelectorAll(".tools-card h4").forEach(function(h){
      if (h.textContent.trim() !== "ZxVAI") return;
      var card = h.closest(".tools-card");
      if (!card) return;
      h.textContent = "Nexus AI";
      var p = card.querySelector("p");
      if (p) p.textContent = "Artificial Intelligence";
      var ic = card.querySelector(".icon i");
      if (ic) ic.className = "fa-solid fa-robot";
      card.removeAttribute("onclick");
      card.onclick = openAiva;
    });
  }

  function addBtn(){
    var nav = document.getElementById("navTabs");
    var oldBtn = document.getElementById("nav-aiva");
    if (oldBtn) oldBtn.remove();
    if (!nav) return;
    patchZx();
  }
  function warmNexusAI(){
    /* Ditunda sampai pengguna membuka Nexus AI agar halaman utama tidak berat. */
  }

  if (document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", function(){
      addBtn();
      if("requestIdleCallback" in window) requestIdleCallback(warmNexusAI,{timeout:900});
      else setTimeout(warmNexusAI,120);
    }, {once:true});
  }else{
    addBtn();
    if("requestIdleCallback" in window) requestIdleCallback(warmNexusAI,{timeout:900});
    else setTimeout(warmNexusAI,120);
  }
})();

/* ===== original script 28: nxAivaEnhanceScript ===== */
(function(){
  'use strict';
  var logoSrc = "data:image/jpeg;base64,";
  var overlayState = {overlay:null, frame:null, back:null};
  function qs(selector, root){ return (root || document).querySelector(selector); }
  function qsa(selector, root){ return Array.prototype.slice.call((root || document).querySelectorAll(selector)); }
  function decorateOverlay(){
    var overlay = qs('#aivaOverlay');
    var frame = overlay && qs('iframe', overlay);
    var back = qs('#aivaBack');
    if(!overlay || !frame || !back) return false;
    overlayState.overlay = overlay; overlayState.frame = frame; overlayState.back = back;
    if(!overlay.querySelector('.nx-aiva-intro')){
      var intro = document.createElement('div');
      intro.className = 'nx-aiva-intro';
      intro.innerHTML = '<div class="nx-aiva-logo-loader"><img src="'+logoSrc+'" alt="Nexus AI"></div>';
      overlay.appendChild(intro);
    }
    return true;
  }
  function tryDecorateIframe(){
    var frame = overlayState.frame || qs('#aivaOverlay iframe'); if(!frame) return;
    try{
      var doc = frame.contentDocument; if(!doc || !doc.body || doc.getElementById('nxAivaInnerBrandStyle')) return;
      var style = doc.createElement('style');
      style.id = 'nxAivaInnerBrandStyle';
      style.textContent = 'body{background-color:#060b18!important;position:relative;overflow-x:hidden!important;}body::before{content:"";position:fixed;inset:0;background-image:linear-gradient(rgba(255,255,255,.02) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.02) 1px,transparent 1px);background-size:26px 26px;pointer-events:none;opacity:.28;z-index:0;}#nxAivaTopBrand{position:fixed;left:14px;bottom:16px;z-index:1;display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:999px;background:rgba(8,14,31,.78);border:1px solid rgba(125,211,252,.16);box-shadow:0 12px 28px rgba(2,6,23,.28);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);pointer-events:none;color:#deecff;font:700 12px/1.2 Inter,system-ui,sans-serif;letter-spacing:.16px;}#nxAivaTopBrand img{width:18px;height:18px;object-fit:contain;display:block;filter:drop-shadow(0 0 10px rgba(96,165,250,.28))}.wc-img,.wc-img.worm-glow{animation:none!important;box-shadow:none!important;transform:none!important}.wc-logo-wrap{animation:none!important}';
      doc.head.appendChild(style);
      var badge = doc.createElement('div'); badge.id = 'nxAivaTopBrand'; badge.innerHTML = '<img src="'+logoSrc+'" alt="N"> <span>Nexus AI</span>'; doc.body.appendChild(badge);
    }catch(error){}
  }
  function showIntro(){
    if(!decorateOverlay()) return;
    var overlay = overlayState.overlay, intro = qs('.nx-aiva-intro', overlay), bar = intro && qs('.nx-aiva-progress span', intro), text = intro && qs('.nx-aiva-progress-text', intro);
    if(!intro) return;
    overlay.classList.remove('ready'); intro.classList.remove('is-hidden'); if(bar) bar.style.width='0%'; if(text) text.textContent='Initializing...';
    requestAnimationFrame(function(){ if(bar) bar.style.width='38%'; });
    setTimeout(function(){ if(bar) bar.style.width='72%'; if(text) text.textContent='Loading interface...'; },240);
    setTimeout(function(){ if(bar) bar.style.width='92%'; if(text) text.textContent='Finalizing...'; },720);
    setTimeout(function(){ if(bar) bar.style.width='100%'; if(text) text.textContent='Nexus AI Ready'; setTimeout(function(){ intro.classList.add('is-hidden'); overlay.classList.add('ready'); tryDecorateIframe(); },220); },1180);
  }
  function openCustomAiva(event){
    if(event){ event.preventDefault(); event.stopPropagation(); }
    if(!decorateOverlay()){
      try{
        if(typeof window.__nxBuildAiva === 'function') window.__nxBuildAiva();
      }catch(error){
        console.warn('[Nexus AI] Gagal menyiapkan ruang AI', error);
      }
    }
    if(!decorateOverlay()) return false;
    qsa('.nav-tab').forEach(function(t){ t.classList.remove('active'); });
    var currentBtn = qs('#nav-aiva'); if(currentBtn) currentBtn.classList.add('active');
    overlayState.overlay.style.display='block'; overlayState.back.style.display='flex';
    requestAnimationFrame(function(){ overlayState.overlay.classList.add('on'); showIntro(); });
    return false;
  }
  function ensureCardIconAndHandlers(){
    qsa('.tools-card').forEach(function(card){
      var h = qs('h4', card);
      if(!h || h.textContent.trim() !== 'Nexus AI') return;
      if(card.getAttribute('data-nx-aiva-patched') === '1') return;

      var iconWrap = qs('.icon', card);
      var robotIcon = iconWrap && iconWrap.querySelector('i.fa-robot');
      if(iconWrap && !robotIcon){
        iconWrap.innerHTML = '<i class="fa-solid fa-robot"></i>';
      }

      card.removeAttribute('onclick');
      card.onclick = openCustomAiva;
      card.setAttribute('data-nx-aiva-patched','1');
    });
  }
  function init(){
    ensureCardIconAndHandlers(); decorateOverlay();
    var observerQueued = false;
    var observer = new MutationObserver(function(){
      if(observerQueued) return;
      observerQueued = true;
      requestAnimationFrame(function(){
        observerQueued = false;
        ensureCardIconAndHandlers();
        decorateOverlay();
        tryDecorateIframe();
      });
    });
    observer.observe(document.body,{childList:true,subtree:true});
    var frame = qs('#aivaOverlay iframe'); if(frame){ frame.addEventListener('load', tryDecorateIframe); setTimeout(tryDecorateIframe,1200); }
    window.addEventListener('message', function(ev){ if(ev.data && ev.data.__atn === 'close'){ var overlay = qs('#aivaOverlay'); if(overlay) overlay.classList.remove('ready'); } });
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true}); else init();
})();

window.openNexusAI = window.openNexusAI || function(event){
  var card = Array.prototype.find.call(document.querySelectorAll('.tools-card'), function(item){
    return item.getAttribute('data-tool-id') === 'zxvai';
  });
  if(card && typeof card.onclick === 'function') return card.onclick(event || null);
  if(typeof window.__nxOriginalOpenAiva === 'function') return window.__nxOriginalOpenAiva(event || null);
  return false;
};
